            }
        },{
            {
                0,1
            },{
                -1,0
            }
        }
    };
    public:bool hasValidPath(vector<vector<int>>& grid){
        int rows=grid.size(),cols=grid[0].size();
        vector<vector<bool>> seen(rows,vector<bool>(cols));
        queue<pair<int,int>> pending;
        pending.push({
            0,0
        });
        seen[0][0]=true;
        while(!pending.empty()){
            auto [row,col]=pending.front();
            pending.pop();
            if(row==rows-1&&col==cols-1)return true;
            for(auto [dr,dc]:paths[grid[row][col]]){
                int nr=row+dr,nc=col+dc;
                if(nr<0||nr>=rows||nc<0||nc>=cols||seen[nr][nc])continue;
                for(auto [br,bc]:paths[grid[nr][nc]])if(br==-dr&&bc==-dc){
                    seen[nr][nc]=true;
                    pending.push({
                        nr,nc
                    });
                    break;
                }
            }
        }
        return false;
    }
};
